import {
  ChevronRight,
  FolderGit2,
  FolderPlus,
  PanelLeftClose,
  Plus,
  Settings2,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { combineActivitySummaries, type ActivitySummary } from "../lib/activity";
import { cn } from "../lib/cn";
import { isMacShortcutPlatform } from "../lib/shortcuts";
import {
  getMigratedItem,
  SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY,
  SIDEBAR_WIDTH_STORAGE_KEY,
} from "../lib/storageKeys";
import type { RegisteredProject } from "../lib/tauri";
import { worktreeIdentity, type ActiveAgent, type DirtyState, type Worktree } from "../lib/types";
import { IconButton } from "./ui/IconButton";
import { StatusDot } from "./ui/StatusDot";
import { WorktreeList } from "./WorktreeList";

export { SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY, SIDEBAR_WIDTH_STORAGE_KEY };
const DEFAULT_SIDEBAR_WIDTH = 236;
const MIN_SIDEBAR_WIDTH = 220;
const MAX_SIDEBAR_WIDTH = 420;

type SidebarProps = {
  open?: boolean;
  isMac?: boolean;
  projects?: RegisteredProject[];
  activeProjectId?: string;
  worktrees: Worktree[];
  agents: ActiveAgent[];
  activePath: string;
  statuses?: Record<string, DirtyState | undefined>;
  unreadWorktreePaths?: Record<string, boolean>;
  activityByWorktreePath?: Record<string, ActivitySummary | undefined>;
  onSelectProject?: (project: RegisteredProject) => void;
  onAddProject?: () => void;
  onSelectWorktree: (worktree: Worktree) => void;
  onCreateWorktree: (project?: RegisteredProject) => void;
  onRefreshWorktreeStatus?: (worktree: Worktree) => void;
  onDeleteWorktree?: (worktree: Worktree) => void;
  onOpenCommandPalette?: () => void;
  onOpenSettings?: () => void;
  onToggle?: () => void;
  onHide?: () => void;
};

export function Sidebar({
  open = true,
  isMac = isMacShortcutPlatform(),
  projects = [],
  activeProjectId,
  worktrees,
  agents,
  activePath,
  statuses = {},
  unreadWorktreePaths,
  activityByWorktreePath,
  onSelectProject = () => undefined,
  onAddProject = () => undefined,
  onSelectWorktree,
  onCreateWorktree,
  onRefreshWorktreeStatus = () => undefined,
  onDeleteWorktree = () => undefined,
  onOpenSettings,
  onToggle,
  onHide,
}: SidebarProps) {
  const worktreeRegionRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<{ startX: number; startWidth: number } | null>(null);
  const [width, setWidth] = useState(loadSidebarWidth);
  const widthRef = useRef(width);
  widthRef.current = width;

  // Accordion state is stored as the set of *collapsed* projects, so each project keeps its own
  // open/closed state and toggling one never disturbs another. Projects the user has never
  // toggled default to collapsed unless they are the active project.
  const [collapsedProjects, setCollapsedProjects] = useState<Set<string>>(() => {
    const stored = loadCollapsedProjects();
    // Once the user has toggled anything the persisted set is authoritative; only a first run
    // (nothing persisted) falls back to "everything but the active project starts collapsed".
    return stored ?? seedCollapsedProjects(new Set<string>(), projects, activeProjectId);
  });
  const knownProjectsRef = useRef<Set<string>>(new Set(projects.map((project) => project.workspaceId)));

  useEffect(() => {
    // Projects registered after mount inherit the same default as the initial seed.
    const unseen = projects.filter((project) => !knownProjectsRef.current.has(project.workspaceId));
    if (unseen.length === 0) return;
    for (const project of unseen) knownProjectsRef.current.add(project.workspaceId);
    setCollapsedProjects((current) => seedCollapsedProjects(current, unseen, activeProjectId));
  }, [activeProjectId, projects]);

  const toggleProject = useCallback((workspaceId: string) => {
    setCollapsedProjects((current) => {
      const next = new Set(current);
      if (next.has(workspaceId)) next.delete(workspaceId);
      else next.add(workspaceId);
      persistCollapsedProjects(next);
      return next;
    });
  }, []);

  const worktreesByProject = useMemo(
    () => groupWorktreesByProject(worktrees, projects, activeProjectId),
    [activeProjectId, projects, worktrees],
  );

  useEffect(() => {
    const handlePointerMove = (event: PointerEvent) => {
      const drag = dragRef.current;
      if (!drag) return;
      const nextWidth = clampSidebarWidth(drag.startWidth + event.clientX - drag.startX);
      widthRef.current = nextWidth;
      setWidth(nextWidth);
    };

    const finishDrag = () => {
      if (!dragRef.current) return;
      dragRef.current = null;
      persistSidebarWidth(widthRef.current);
      document.body.style.cursor = "";
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", finishDrag);
    window.addEventListener("pointercancel", finishDrag);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", finishDrag);
      window.removeEventListener("pointercancel", finishDrag);
      document.body.style.cursor = "";
    };
  }, []);

  const startResize = (event: React.PointerEvent<HTMLDivElement>) => {
    event.preventDefault();
    dragRef.current = { startX: event.clientX, startWidth: widthRef.current };
    document.body.style.cursor = "col-resize";
  };

  if (!open) {
    return null;
  }

  return (
    <aside
      className="relative flex h-full shrink-0 flex-col overflow-hidden bg-worktree-sidebar text-worktree-sidebar-foreground"
      style={{ width: `${width}px`, minWidth: `${MIN_SIDEBAR_WIDTH}px`, maxWidth: `${MAX_SIDEBAR_WIDTH}px` }}
    >
      <div
        data-testid="sidebar-drag-region"
        data-tauri-drag-region
        className="drag-region flex h-titlebar shrink-0 items-center px-2"
      >
        {isMac ? <div data-testid="titlebar-traffic-light-pad" className="w-[72px] shrink-0" aria-hidden="true" /> : null}
        <IconButton
          label="Hide sidebar"
          className="no-drag"
          size="sm"
          onClick={onToggle ?? onHide}
        >
          <PanelLeftClose className="size-3.5" />
        </IconButton>
        <IconButton label="Add worktree" className="no-drag" size="sm" onClick={() => onCreateWorktree()}>
          <FolderPlus className="size-3.5" />
        </IconButton>
        <IconButton label="Add project" className="no-drag" size="sm" onClick={onAddProject}>
          <Plus className="size-3.5" />
        </IconButton>
      </div>

      <div ref={worktreeRegionRef} tabIndex={-1} data-testid="worktree-region" className="flex min-h-0 flex-1 flex-col outline-none">
        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden px-2 pt-2 pb-2 scrollbar-sleek">
          {projects.length === 0 ? (
            <p className="px-2 py-3 text-[11px] leading-relaxed text-muted-foreground">
              No projects registered yet.
            </p>
          ) : null}

          {projects.map((project) => {
            const active = project.workspaceId === activeProjectId;
            const expanded = !collapsedProjects.has(project.workspaceId);
            const projectWorktrees = worktreesByProject.get(project.workspaceId) ?? [];
            const projectActivity = summarizeProjectActivity(
              projectWorktrees,
              activityByWorktreePath,
              unreadWorktreePaths,
            );
            const attentionState = projectActivity.hasWaiting
              ? "waiting"
              : projectActivity.hasUnread
                ? "unread"
                : null;

            return (
              <div key={project.workspaceId} className="pb-0.5">
                <div
                  className={cn(
                    "group/project flex h-7 w-full items-center gap-0.5 rounded-md pr-1 transition-colors",
                    active
                      ? "bg-worktree-sidebar-accent font-medium text-worktree-sidebar-accent-foreground"
                      : "text-worktree-sidebar-foreground/65 hover:bg-worktree-sidebar-accent/60 hover:text-worktree-sidebar-foreground",
                  )}
                >
                  <button
                    type="button"
                    onClick={() => toggleProject(project.workspaceId)}
                    aria-expanded={expanded}
                    aria-label={`${expanded ? "Collapse" : "Expand"} ${project.workspaceId}`}
                    className="flex size-5 shrink-0 items-center justify-center rounded-sm text-muted-foreground transition-colors hover:text-worktree-sidebar-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                  >
                    <ChevronRight
                      aria-hidden="true"
                      className={cn("size-3 shrink-0 transition-transform", expanded && "rotate-90")}
                    />
                  </button>
                  <button
                    type="button"
                    onClick={() => onSelectProject(project)}
                    aria-current={active ? "true" : undefined}
                    aria-label={project.workspaceId}
                    className="flex min-w-0 flex-1 items-center gap-1.5 rounded-sm py-1 text-left text-[12px] focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                  >
                    <FolderGit2 className="size-3.5 shrink-0" />
                    <span className="min-w-0 flex-1 truncate">{project.workspaceId}</span>
                    {projectActivity.runningCount > 0 ? (
                      <span
                        data-testid="project-running-badge"
                        className="shrink-0 rounded-full bg-status-working/12 px-1.5 py-px text-[9px] font-medium leading-none text-status-working"
                      >
                        {projectActivity.runningCount} running
                      </span>
                    ) : null}
                    {attentionState ? (
                      <span
                        data-testid="project-attention-indicator"
                        data-attention-state={attentionState}
                        title={attentionState === "waiting" ? "Agent needs attention" : "Unread activity"}
                        className="inline-flex size-3 shrink-0 items-center justify-center"
                      >
                        <StatusDot state={attentionState} />
                      </span>
                    ) : null}
                  </button>
                </div>

                {expanded ? (
                  <div className="pl-3 pr-0.5 pt-0.5">
                    <WorktreeList
                      worktrees={projectWorktrees}
                      agents={agents}
                      activePath={active ? activePath : ""}
                      statuses={statuses}
                      unreadWorktreePaths={unreadWorktreePaths}
                      activityByWorktreePath={activityByWorktreePath}
                      onSelect={onSelectWorktree}
                      onCreate={() => onCreateWorktree(project)}
                      onRefreshStatus={onRefreshWorktreeStatus}
                      onDelete={onDeleteWorktree}
                      label={`${project.workspaceId} worktrees`}
                    />
                  </div>
                ) : null}
              </div>
            );
          })}
        </div>
      </div>

      <div className="flex shrink-0 items-center justify-between border-t border-worktree-sidebar-border px-2 py-1.5">
        <div className="flex items-center gap-2 px-1 text-[10px] text-muted-foreground">
          <span className="size-1.5 rounded-full bg-status-success" />
          Local runtime
        </div>
        <IconButton label="Settings" size="sm" onClick={onOpenSettings}>
          <Settings2 className="size-3.5" />
        </IconButton>
      </div>

      <div
        role="separator"
        aria-label="Resize sidebar"
        aria-orientation="vertical"
        aria-valuemin={MIN_SIDEBAR_WIDTH}
        aria-valuemax={MAX_SIDEBAR_WIDTH}
        aria-valuenow={width}
        onPointerDown={startResize}
        className="no-drag absolute inset-y-0 right-0 z-30 w-1.5 cursor-col-resize touch-none"
      >
        <span className="pointer-events-none absolute inset-y-0 right-0 w-px bg-worktree-sidebar-border transition-colors group-hover:bg-ring/45" />
      </div>
    </aside>
  );
}

function summarizeProjectActivity(
  worktrees: Worktree[],
  activityByWorktreePath: Record<string, ActivitySummary | undefined> | undefined,
  unreadWorktreePaths: Record<string, boolean> | undefined,
): ActivitySummary {
  const summaries = worktrees
    .map((worktree) => activityByWorktreePath?.[worktree.path])
    .filter((summary): summary is ActivitySummary => Boolean(summary));
  const hasUnread = worktrees.some((worktree) => Boolean(unreadWorktreePaths?.[worktree.path]));
  return combineActivitySummaries(summaries, hasUnread);
}

/**
 * Worktrees carry their owning project inside their `orca/<wsId>/<slug>` branch name. Anything
 * without a matching registered project belongs to the active project, which is the only project
 * whose worktrees the workspace store actually holds.
 */
function groupWorktreesByProject(
  worktrees: Worktree[],
  projects: RegisteredProject[],
  activeProjectId: string | undefined,
) {
  const grouped = new Map<string, Worktree[]>();
  for (const project of projects) grouped.set(project.workspaceId, []);

  for (const worktree of worktrees) {
    const ownerId = worktreeIdentity(worktree)?.wsId;
    const owner = ownerId && grouped.has(ownerId) ? ownerId : activeProjectId;
    if (!owner) continue;
    const bucket = grouped.get(owner);
    if (bucket) bucket.push(worktree);
  }

  return grouped;
}

function seedCollapsedProjects(
  collapsed: Set<string>,
  projects: RegisteredProject[],
  activeProjectId: string | undefined,
) {
  const seeded = projects.filter(
    (project) => project.workspaceId !== activeProjectId && !collapsed.has(project.workspaceId),
  );
  if (seeded.length === 0) return collapsed;
  const next = new Set(collapsed);
  for (const project of seeded) next.add(project.workspaceId);
  return next;
}

/** Returns `null` when the accordion has never been persisted, so callers can apply defaults. */
function loadCollapsedProjects(): Set<string> | null {
  try {
    const raw = getMigratedItem(SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY);
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return null;
    return new Set(parsed.filter((id): id is string => typeof id === "string"));
  } catch {
    return null;
  }
}

function persistCollapsedProjects(collapsed: Set<string>) {
  try {
    window.localStorage.setItem(SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY, JSON.stringify([...collapsed]));
  } catch {
    // A storage failure should not break accordion toggling for this session.
  }
}

function loadSidebarWidth() {
  try {
    const raw = getMigratedItem(SIDEBAR_WIDTH_STORAGE_KEY);
    const stored = Number(raw);
    return Number.isFinite(stored) && stored > 0 ? clampSidebarWidth(stored) : DEFAULT_SIDEBAR_WIDTH;
  } catch {
    return DEFAULT_SIDEBAR_WIDTH;
  }
}

function persistSidebarWidth(width: number) {
  try {
    window.localStorage.setItem(SIDEBAR_WIDTH_STORAGE_KEY, String(clampSidebarWidth(width)));
  } catch {
    // A storage failure should not break pointer resizing for this session.
  }
}

function clampSidebarWidth(width: number) {
  return Math.min(MAX_SIDEBAR_WIDTH, Math.max(MIN_SIDEBAR_WIDTH, Math.round(width)));
}

import { PanelLeft } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";

import { CommandPalette } from "./components/CommandPalette";
import { AddProjectDialog, AddWorktreeDialog } from "./components/ProjectDialogs";
import { SettingsDialog } from "./components/SettingsDialog";
import { Sidebar } from "./components/Sidebar";
import { TerminalSplitView } from "./components/TerminalSplitView";
import { WorktreeDeleteDialog } from "./components/WorktreeDeleteDialog";
import { IconButton } from "./components/ui/IconButton";
import { deserializeWorkspaceState, serializeWorkspaceState } from "./lib/sessionPersistence";
import { isMacShortcutPlatform, useShortcuts } from "./lib/shortcuts";
import {
  AGENT_CANDIDATES,
  AGENTS_SETTINGS_CHANGED_EVENT,
  getLaunchableAgents,
  loadAgentSettings,
  mergeDetections,
  type AgentSettings,
} from "./lib/agentsSettings";
import {
  ACTIVE_PROJECT_STORAGE_KEY,
  getMigratedItem,
  PROJECTS_STORAGE_KEY,
  SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY,
  SIDEBAR_OPEN_STORAGE_KEY,
} from "./lib/storageKeys";
import {
  DEFAULT_WORKSPACE_ID,
  detectAgents,
  getWorktreeStatus,
  isTauriRuntime,
  loadSession,
  onNewTerminalTabMenu,
  registerProject,
  saveSession,
  spawnTerminal,
  writeTerminal,
  type AgentDetection,
  type RegisteredProject,
} from "./lib/tauri";
import { ensureTerminalEvents } from "./lib/terminalEvents";
import { useTerminalSettings } from "./lib/terminalSettings";
import { defaultTauriTransport } from "./lib/terminalTransport/tauriTransport";
import { worktreeIdentity, type DirtyState, type WorkspaceTab, type Worktree } from "./lib/types";
import { registerWindowCloseGuard } from "./lib/updater";
import { collectLeafIds, type PaneDirection } from "./state/paneTree";
import { useWorkspaceRuntime } from "./state/workspaceRuntime";
import { useWorkspaceStore } from "./state/workspaceStore";

export { ACTIVE_PROJECT_STORAGE_KEY, PROJECTS_STORAGE_KEY, SIDEBAR_OPEN_STORAGE_KEY };
const DEFAULT_PROJECT: RegisteredProject = { workspaceId: DEFAULT_WORKSPACE_ID, repoRoot: "." };

export function App() {
  const [projects, setProjects] = useState<RegisteredProject[]>(loadProjects);
  const [activeProjectId, setActiveProjectId] = useState(loadActiveProjectId);
  const activeProject = useMemo(
    () => projects.find((project) => project.workspaceId === activeProjectId) ?? projects[0] ?? DEFAULT_PROJECT,
    [activeProjectId, projects],
  );

  const [agentSettings, setAgentSettings] = useState<AgentSettings>(loadAgentSettings);
  const [agentDetections, setAgentDetections] = useState<AgentDetection[]>([]);

  useEffect(() => {
    let cancelled = false;
    async function runDetection() {
      if (!isTauriRuntime()) return;
      try {
        const results = await detectAgents([...AGENT_CANDIDATES]);
        if (!cancelled) setAgentDetections(results);
      } catch (error) {
        console.warn("Failed to detect agents:", error);
      }
    }
    void runDetection();
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    const handleSettingsChange = () => {
      setAgentSettings(loadAgentSettings());
    };
    window.addEventListener(AGENTS_SETTINGS_CHANGED_EVENT, handleSettingsChange);
    return () => window.removeEventListener(AGENTS_SETTINGS_CHANGED_EVENT, handleSettingsChange);
  }, []);

  const resolvedAgents = useMemo(
    () => mergeDetections(agentSettings, agentDetections),
    [agentSettings, agentDetections],
  );

  const launchableAgents = useMemo(
    () => getLaunchableAgents(resolvedAgents),
    [resolvedAgents],
  );

  const {
    state,
    agents,
    tabActivity,
    worktreeActivity,
    updateSessionTitleActivity,
    openTab,
    createBrowserTab,
    navigateBrowserTab,
    reloadBrowserTab,
    ensureTabForWorktree,
    closeTab,
    closeOtherTabs,
    closeTabsToRight,
    closeTabsToLeft,
    splitPane,
    moveTabToGroup,
    moveTabToSplit,
    detachPaneToTab,
    closePane,
    activateTab,
    reorderTab,
    renameTab,
    setTabPinned,
    focusPane,
    setPaneRatio,
    setTabGroupRatio,
    swapPanes,
    syncWorktrees,
    restoreWorkspace,
  } = useWorkspaceStore({ workspaceId: activeProject.workspaceId });
  const { runtimeError, refreshWorktrees, reportRuntimeError } = useWorkspaceRuntime({
    workspaceId: activeProject.workspaceId,
    activeWorktreePath: state.activeWorktreePath,
    syncWorktrees,
    ensureTabForWorktree,
  });

  useEffect(() => {
    void registerProject({
      workspaceId: activeProject.workspaceId,
      repoPath: activeProject.repoRoot,
    })
      .then(() => refreshWorktrees())
      .catch(reportRuntimeError);
  }, [activeProject.repoRoot, activeProject.workspaceId, refreshWorktrees, reportRuntimeError]);

  // Initial session restore on startup & HMR recovery.
  useEffect(() => {
    let cancelled = false;
    async function restore() {
      try {
        const session = await loadSession();
        if (cancelled || !session) return;

        const liveSessions = await defaultTauriTransport.listSessions().catch(() => []);
        const liveBackendIds = new Set(liveSessions.map((candidate) => candidate.sessionId));
        const restoredState = deserializeWorkspaceState(activeProject.workspaceId, session, liveBackendIds);

        if (restoredState && restoredState.layout.tabs.length > 0) {
          restoreWorkspace(restoredState);

          // A persisted local session can outlive its native PTY. Respawn only the dead
          // native side while preserving the local session/leaf ownership graph.
          const deadSessions = Object.values(restoredState.sessions).filter((candidate) => !candidate.backendSessionId);
          if (deadSessions.length > 0) {
            let hasSpawned = false;
            await ensureTerminalEvents().catch(() => undefined);
            for (const restoredSession of deadSessions) {
              if (cancelled) return;
              try {
                const worktreePath = restoredSession.worktreePath ?? restoredSession.cwd;
                const foundWorktree = restoredState.worktrees.find((worktree) => worktree.path === worktreePath);
                const backendSessionId = await spawnTerminal({
                  workspaceId: activeProject.workspaceId,
                  worktree: foundWorktree ? worktreeIdentity(foundWorktree) : null,
                  cwd: restoredSession.cwd,
                });
                restoredSession.backendSessionId = backendSessionId;
                restoredSession.lifecycle = "working";
                hasSpawned = true;
              } catch (error) {
                console.warn("Failed to respawn terminal session on restore:", error);
              }
            }

            if (hasSpawned && !cancelled) restoreWorkspace({ ...restoredState });
          }
          // Typed v2 restoration already reconstructed every tab. Do not run the legacy
          // per-worktree fallback as well or it can create duplicate terminal tabs.
          return;
        }

        // Legacy best-effort fallback for sessions that cannot be deserialized as a
        // workspace state. Browser records are skipped because they require explicit v2
        // browser metadata and should never be guessed from terminal fields.
        const workspace = session.workspaces?.[activeProject.workspaceId];
        if (!workspace || !workspace.layout?.tabs?.length) return;
        for (const persistedTab of workspace.layout.tabs) {
          if (cancelled) return;
          if (persistedTab.kind === "browser") continue;
          const legacyWorktreePath = persistedTab.worktreePath || workspace.repoRoot;
          const found = workspace.worktrees?.find((candidate) => candidate.path === legacyWorktreePath);
          const worktree: Worktree = found
            ? {
                path: found.path,
                head: found.head,
                branch: found.branch,
                bare: false,
                detached: false,
                locked: found.isLocked ? "locked" : null,
                prunable: null,
              }
            : {
                path: legacyWorktreePath,
                head: "",
                branch: persistedTab.label,
                bare: false,
                detached: false,
                locked: null,
                prunable: null,
              };
          try {
            const alreadyOpen = state.layout.tabs.some((tab) => {
              if (tab.kind === "browser") return false;
              const localSession = state.sessions[tab.sessionId];
              return (localSession?.worktreePath ?? localSession?.cwd) === worktree.path;
            });
            if (!alreadyOpen) await ensureTabForWorktree(worktree);
          } catch {
            // Safe fallback if the terminal for this worktree is already open.
          }
        }
      } catch (error) {
        console.warn("Session restore on boot skipped:", error);
      }
    }
    void restore();
    return () => {
      cancelled = true;
    };
  }, [activeProject.workspaceId, ensureTabForWorktree, restoreWorkspace, state.layout.tabs, state.sessions]);

  useEffect(() => {
    const unregister = registerWindowCloseGuard(async () => {
      const session = serializeWorkspaceState(activeProject.workspaceId, activeProject.repoRoot, state);
      await saveSession(session);
    });
    return unregister;
  }, [activeProject.repoRoot, activeProject.workspaceId, state]);

  useEffect(() => {
    if (state.worktrees.length === 0 || state.layout.tabs.length === 0) return;
    const timer = setTimeout(() => {
      const session = serializeWorkspaceState(activeProject.workspaceId, activeProject.repoRoot, state);
      void Promise.resolve(saveSession(session)).catch((error) => console.error("Failed to auto-save session:", error));
    }, 500);
    return () => clearTimeout(timer);
  }, [activeProject.repoRoot, activeProject.workspaceId, state]);

  const [isAddProjectOpen, setIsAddProjectOpen] = useState(false);
  const [createTargetProject, setCreateTargetProject] = useState<RegisteredProject | null>(null);
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isCommandPaletteOpen, setIsCommandPaletteOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [searchLeafId, setSearchLeafId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(loadSidebarOpen);
  const [deleteTarget, setDeleteTarget] = useState<Worktree | null>(null);
  const [worktreeStatuses, setWorktreeStatuses] = useState<Record<string, DirtyState | undefined>>({});
  const [pendingWorktreePath, setPendingWorktreePath] = useState<string | null>(null);

  const toggleSidebar = useCallback(() => {
    setIsSidebarOpen((current) => {
      const next = !current;
      persistSidebarOpen(next);
      return next;
    });
  }, []);

  const activeWorktree = useMemo(
    () => state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? null,
    [state.activeWorktreePath, state.worktrees],
  );

  const handleSelectProject = useCallback(
    (project: RegisteredProject) => {
      if (project.workspaceId === activeProject.workspaceId) return;
      setActiveProjectId(project.workspaceId);
      persistActiveProjectId(project.workspaceId);
      setWorktreeStatuses({});
      setDeleteTarget(null);
      setPendingWorktreePath(null);
    },
    [activeProject.workspaceId],
  );

  const handleRegisteredProject = useCallback((project: RegisteredProject) => {
    setProjects((current) => {
      const next = [...current.filter((candidate) => candidate.workspaceId !== project.workspaceId), project];
      persistProjects(next);
      return next;
    });
    setActiveProjectId(project.workspaceId);
    persistActiveProjectId(project.workspaceId);
    setWorktreeStatuses({});
  }, []);

  const handleSelectWorktree = useCallback(
    (worktree: Worktree) => {
      const ownerId = worktreeIdentity(worktree)?.wsId;
      const owner = ownerId ? projects.find((project) => project.workspaceId === ownerId) : undefined;
      if (owner && owner.workspaceId !== activeProject.workspaceId) {
        handleSelectProject(owner);
        setPendingWorktreePath(worktree.path);
        return;
      }
      void ensureTabForWorktree(worktree).catch(reportRuntimeError);
    },
    [activeProject.workspaceId, ensureTabForWorktree, handleSelectProject, projects, reportRuntimeError],
  );

  useEffect(() => {
    if (!pendingWorktreePath) return;
    const target = state.worktrees.find((worktree) => worktree.path === pendingWorktreePath);
    if (!target) return;
    setPendingWorktreePath(null);
    void ensureTabForWorktree(target).catch(reportRuntimeError);
  }, [ensureTabForWorktree, pendingWorktreePath, reportRuntimeError, state.worktrees]);

  const handleSelectTerminalTab = useCallback(
    (tabId: string) => {
      const tab = state.layout.tabs.find((candidate) => candidate.id === tabId);
      if (!tab) return;
      if (tab.kind === "browser") {
        activateTab(tabId);
        return;
      }
      const session = state.sessions[tab.sessionId];
      const sessionWorktreePath = session?.worktreePath ?? session?.cwd;
      const worktree = sessionWorktreePath
        ? state.worktrees.find((candidate) => candidate.path === sessionWorktreePath)
        : undefined;
      if (!worktree || worktree.path === state.activeWorktreePath) {
        activateTab(tabId);
        return;
      }
      void ensureTabForWorktree(worktree)
        .then(() => activateTab(tabId))
        .catch(reportRuntimeError);
    },
    [activateTab, ensureTabForWorktree, reportRuntimeError, state.activeWorktreePath, state.layout.tabs, state.sessions, state.worktrees],
  );

  const handleRefreshWorktreeStatus = useCallback(
    (worktree: Worktree) => {
      const identity = worktreeIdentity(worktree);
      if (!identity) return;
      void getWorktreeStatus({ workspaceId: activeProject.workspaceId, worktree: identity })
        .then((status) => {
          setWorktreeStatuses((current) => ({ ...current, [worktree.path]: status }));
        })
        .catch(reportRuntimeError);
    },
    [activeProject.workspaceId, reportRuntimeError],
  );

  const handleAddTerminalTab = useCallback(() => {
    if (!activeWorktree) return;
    void openTab(activeWorktree).catch(reportRuntimeError);
  }, [activeWorktree, openTab, reportRuntimeError]);

  const handleLaunchAgent = useCallback(
    async (agent: { name: string; command: string; args: string }) => {
      try {
        const targetWorktree = activeWorktree ?? state.worktrees[0];
        if (!targetWorktree) return;
        await ensureTerminalEvents().catch(() => undefined);
        const backendSessionId = await spawnTerminal({
          workspaceId: activeProject.workspaceId,
          worktree: worktreeIdentity(targetWorktree),
          cwd: targetWorktree.path,
        });
        const label = agent.name.charAt(0).toUpperCase() + agent.name.slice(1);
        await openTab(targetWorktree, label, backendSessionId);
        const fullCommand = `${agent.command} ${agent.args}`.trim();
        if (fullCommand) {
          await writeTerminal({ sessionId: backendSessionId, data: `${fullCommand}\r` });
        }
      } catch (error) {
        reportRuntimeError(error);
      }
    },
    [activeProject.workspaceId, activeWorktree, openTab, reportRuntimeError, state.worktrees],
  );

  useEffect(() => {
    let unlisten: (() => void) | null = null;
    let cancelled = false;
    void onNewTerminalTabMenu(handleAddTerminalTab).then((dispose) => {
      if (cancelled) dispose();
      else unlisten = dispose;
    });
    return () => {
      cancelled = true;
      unlisten?.();
    };
  }, [handleAddTerminalTab]);

  const handleCloseTab = useCallback(
    (tabId: string) => {
      void closeTab(tabId).catch(reportRuntimeError);
    },
    [closeTab, reportRuntimeError],
  );

  const handleCloseOtherTabs = useCallback(
    (tabId: string) => {
      void closeOtherTabs(tabId).catch(reportRuntimeError);
    },
    [closeOtherTabs, reportRuntimeError],
  );

  const handleCloseTabsToRight = useCallback(
    (tabId: string) => {
      void closeTabsToRight(tabId).catch(reportRuntimeError);
    },
    [closeTabsToRight, reportRuntimeError],
  );

  const handleCloseTabsToLeft = useCallback(
    (tabId: string) => {
      void closeTabsToLeft(tabId).catch(reportRuntimeError);
    },
    [closeTabsToLeft, reportRuntimeError],
  );

  const handleCycleTab = useCallback(
    (offset: number) => {
      const focusedGroup = state.layout.focusedGroupId
        ? state.layout.tabGroups?.[state.layout.focusedGroupId]
        : undefined;
      const tabById = new Map(state.layout.tabs.map((tab) => [tab.id, tab]));
      const tabs: WorkspaceTab[] = focusedGroup
        ? focusedGroup.tabIds.map((tabId) => tabById.get(tabId)).filter((tab): tab is WorkspaceTab => Boolean(tab))
        : state.layout.tabs;
      if (tabs.length < 2) return;
      const currentIndex = Math.max(0, tabs.findIndex((tab) => tab.id === state.layout.activeTabId));
      const nextIndex = (currentIndex + offset + tabs.length) % tabs.length;
      handleSelectTerminalTab(tabs[nextIndex].id);
    },
    [handleSelectTerminalTab, state.layout.activeTabId, state.layout.focusedGroupId, state.layout.tabGroups, state.layout.tabs],
  );

  const handleSplitActive = useCallback(
    (direction: PaneDirection) => {
      const activeTab = state.layout.tabs.find((tab) => tab.id === state.layout.activeTabId) ?? state.layout.tabs[0];
      if (!activeTab || activeTab.kind === "browser") return;
      const activeLayout = state.layout.layoutsByTabId?.[activeTab.id];
      const targetLeafId = activeLayout?.activeLeafId ?? "leaf-default";
      void splitPane(activeTab.id, targetLeafId, direction).catch(reportRuntimeError);
    },
    [reportRuntimeError, splitPane, state.layout.activeTabId, state.layout.layoutsByTabId, state.layout.tabs],
  );

  const handleUnsplitActive = useCallback(() => {
    const activeTab = state.layout.tabs.find((tab) => tab.id === state.layout.activeTabId) ?? state.layout.tabs[0];
    if (!activeTab || activeTab.kind === "browser") return;
    const activeLayout = state.layout.layoutsByTabId?.[activeTab.id];
    if (!activeLayout || activeLayout.root.type === "leaf") return;
    const activeLeafId = activeLayout.activeLeafId ?? "leaf-default";
    void closePane(activeTab.id, activeLeafId).catch(reportRuntimeError);
  }, [closePane, reportRuntimeError, state.layout.activeTabId, state.layout.layoutsByTabId, state.layout.tabs]);

  const handleCyclePaneFocus = useCallback(
    (offset: number) => {
      const activeTab = state.layout.tabs.find((tab) => tab.id === state.layout.activeTabId) ?? state.layout.tabs[0];
      if (!activeTab || activeTab.kind === "browser") return;
      const activeLayout = state.layout.layoutsByTabId?.[activeTab.id];
      if (!activeLayout) return;
      const leafIds = collectLeafIds(activeLayout.root);
      if (leafIds.length < 2) return;
      const activeLeafId = activeLayout.activeLeafId ?? leafIds[0];
      const currentIndex = Math.max(0, leafIds.indexOf(activeLeafId));
      const nextIndex = (currentIndex + offset + leafIds.length) % leafIds.length;
      focusPane(activeTab.id, leafIds[nextIndex]);
    },
    [focusPane, state.layout.activeTabId, state.layout.layoutsByTabId, state.layout.tabs],
  );

  const handleOpenTerminalSearch = useCallback(() => {
    const activeTab = state.layout.tabs.find((tab) => tab.id === state.layout.activeTabId) ?? state.layout.tabs[0];
    if (!activeTab || activeTab.kind === "browser") return;
    const activeLayout = state.layout.layoutsByTabId?.[activeTab.id];
    const leafId = activeLayout?.activeLeafId ?? (activeLayout?.root ? collectLeafIds(activeLayout.root)[0] : "leaf-default");
    setSearchLeafId(leafId);
  }, [state.layout.activeTabId, state.layout.layoutsByTabId, state.layout.tabs]);

  const handleSelectWorktreeByIndex = useCallback(
    (index: number) => {
      const visible = listVisibleWorktrees(projects, state.worktrees, activeProject.workspaceId);
      const target = visible[index];
      if (target) handleSelectWorktree(target);
    },
    [activeProject.workspaceId, handleSelectWorktree, projects, state.worktrees],
  );

  const { settings: terminalSettings, updateSettings: updateTerminalSettings } = useTerminalSettings();

  const handleZoomIn = useCallback(() => {
    const nextSize = Math.min(36, terminalSettings.fontSize + 1);
    updateTerminalSettings({ fontSize: nextSize });
  }, [terminalSettings.fontSize, updateTerminalSettings]);

  const handleZoomOut = useCallback(() => {
    const nextSize = Math.max(10, terminalSettings.fontSize - 1);
    updateTerminalSettings({ fontSize: nextSize });
  }, [terminalSettings.fontSize, updateTerminalSettings]);

  const handleZoomReset = useCallback(() => {
    updateTerminalSettings({ fontSize: null });
  }, [updateTerminalSettings]);

  const handleSelectTerminalTabByIndex = useCallback(
    (index: number) => {
      const focusedGroup = state.layout.focusedGroupId
        ? state.layout.tabGroups?.[state.layout.focusedGroupId]
        : undefined;
      const tabId = focusedGroup?.tabIds[index] ?? state.layout.tabs[index]?.id;
      if (tabId) handleSelectTerminalTab(tabId);
    },
    [handleSelectTerminalTab, state.layout.focusedGroupId, state.layout.tabGroups, state.layout.tabs],
  );

